"""Editorial content for CC-12, Civil Code arts. 1495-1605 and 1510-A-E."""

def row(says, means, example, warning, term, definition):
    return {"target": None, "o_que_diz": says, "o_que_significa": means, "exemplo_pratico": example, "atencao": warning, "palavras_dificeis": [{"termo": term, "explicacao": definition}]}

_DATA = {
"1495": ("Título que menciona hipoteca anterior ainda sem registro provoca prenotação e espera de trinta dias; sem inscrição da precedente, registra-se a posterior com a prioridade então obtida.", "A regra protege a ordem registral e oferece oportunidade limitada para tornar pública a garantia anterior.", "O cartório aguarda trinta dias pela primeira hipoteca antes de registrar a segunda.", "A preferência depende da providência registral dentro do prazo, não apenas da data do contrato.", "Prenotação", "lançamento provisório que reserva prioridade ao título apresentado"),
"1496": ("Mesmo duvidando da legalidade do pedido, o oficial o prenota; se a dúvida for afastada em noventa dias, conserva-se a posição original, caso contrário a nova apresentação recebe outra ordem.", "A discussão registral não elimina imediatamente a prioridade temporal do requerente.", "A dúvida é julgada improcedente e a hipoteca mantém o número correspondente à prenotação.", "A manutenção da prioridade pressupõe solução favorável dentro do regime e do prazo legais.", "Dúvida registral", "procedimento para decidir objeção jurídica levantada pelo registrador"),
"1497": ("Hipotecas legais precisam de registro e individualização; o obrigado deve promovê-los, sem impedir atuação do interessado ou do Ministério Público, e responde por omissão danosa.", "A garantia criada pela lei só ganha adequada publicidade e delimitação após as formalidades registrárias.", "Responsável não especializa imóvel que garante patrimônio de incapaz e indeniza o prejuízo.", "A hipoteca legal não dispensa identificar bens e valor garantido nem afasta perdas e danos.", "Especialização", "determinação precisa do bem e da dívida abrangidos pela garantia"),
"1498": ("O registro hipotecário acompanha a duração da obrigação, mas a especialização deve ser renovada ao completar vinte anos.", "A garantia pode subsistir enquanto houver dívida, embora sua delimitação registral exija atualização periódica.", "Dívida longa continua garantida após renovação da especialização no vigésimo ano.", "Não se deve confundir duração da obrigação com a formalidade de renovar a especialização.", "Renovação", "atualização formal necessária para conservar a individualização registral"),
"1499": ("A hipoteca termina com a obrigação principal, perecimento do bem, resolução da propriedade, renúncia, remição, arrematação ou adjudicação.", "A lista reúne fatos que retiram a dívida, o objeto, o direito do garantidor ou a própria garantia.", "Quitada a dívida, desaparece a causa da hipoteca e cabe seu cancelamento registral.", "Algumas causas ainda exigem averbação e a arrematação observa a proteção do credor notificado.", "Remição", "liberação do bem mediante pagamento da dívida garantida"),
"1500": ("A hipoteca também se extingue quando seu cancelamento, comprovado por documento adequado, é averbado no Registro de Imóveis.", "A publicidade registral formaliza perante terceiros o fim da garantia.", "O proprietário apresenta quitação e obtém a averbação do cancelamento.", "Pagamento sem baixa registral pode deixar aparência de gravame e exige regularização.", "Averbação", "anotação registral que atualiza situação jurídica já inscrita"),
"1501": ("Arrematação ou adjudicação não elimina hipoteca registrada quando o credor hipotecário, alheio à execução, não foi judicialmente notificado.", "A venda judicial não pode apagar garantia sem permitir participação do titular protegido pelo registro.", "Imóvel é adjudicado sem ciência do banco hipotecário e o gravame não se extingue por esse ato.", "A regra alcança credor que não participou de outro modo da execução; a notificação deve ser judicial.", "Adjudicação", "transferência judicial do bem ao credor ou interessado habilitado"),
"1502": ("Hipoteca de estrada de ferro é registrada no município onde se situa a estação inicial da linha.", "A norma fixa competência territorial específica para centralizar a publicidade da garantia ferroviária.", "Linha iniciada no Município A tem ali registrada a hipoteca, embora atravesse outras cidades.", "Outros bens ou garantias podem seguir competências registrais diferentes.", "Competência territorial", "local legalmente designado para a prática do registro"),
"1503": ("Credores hipotecários não podem impedir a exploração ferroviária nem as alterações administrativas na via, dependências ou material.", "A garantia não transfere gestão da atividade nem paralisa serviço e decisões operacionais.", "Banco não pode vetar troca de trilhos decidida pela administração da ferrovia.", "A liberdade operacional não autoriza atos destinados a esvaziar fraudulentamente a garantia.", "Exploração da linha", "operação econômica e técnica do serviço ferroviário"),
"1504": ("A garantia ferroviária alcança linhas descritas e material existente na execução; credores podem opor-se a alienação relevante ou fusão que enfraqueça o crédito.", "O objeto acompanha a estrutura operacional, mas atos extraordinários prejudiciais admitem reação do credor.", "Credor contesta venda de grande parte dos vagões que reduziria a suficiência da hipoteca.", "A oposição exige risco de enfraquecimento e não equivale a controle cotidiano da empresa.", "Material de exploração", "equipamentos e bens empregados no funcionamento da ferrovia"),
"1505": ("Na execução da hipoteca ferroviária, representante da União ou do Estado é intimado para, em quinze dias, remir a estrada pelo preço judicial.", "O poder público recebe oportunidade de preservar a infraestrutura mediante pagamento da arrematação ou adjudicação.", "Estado paga o preço dentro do prazo e evita transferência da linha ao arrematante.", "A remição depende de intimação e pagamento integral no prazo específico.", "Remir", "liberar ou adquirir o bem mediante pagamento do valor legalmente exigido"),
"1506": ("Anticrese permite entregar imóvel ao credor para que frutos e rendimentos amortizem dívida ou juros; excedente acima do limite legal reduz o capital e pode coexistir com hipoteca.", "A posse produtiva funciona como garantia e forma de pagamento, sujeita a prestação de contas e limites financeiros.", "Credor administra imóvel alugado e imputa os aluguéis primeiro aos juros permitidos e depois ao principal.", "O credor não se torna proprietário e deve respeitar teto legal, imputação e eventual hipoteca concorrente.", "Anticrese", "garantia real em que o credor recebe frutos de imóvel entregue"),
"1507": ("O credor anticrético administra e frui o imóvel, presta balanço anual e pode arrendá-lo salvo pacto contrário; gestão ruim admite impugnação e conversão judicial em arrendamento.", "A ampla administração vem acompanhada de transparência, controle do devedor e retenção até pagamento.", "Devedor questiona contas inexatas e pede ao juiz aluguel mensal em lugar da gestão direta.", "Arrendamento a terceiro não vincula automaticamente o devedor e não elimina o dever de contas.", "Balanço", "demonstrativo organizado das receitas, despesas e resultado da administração"),
"1508": ("O credor anticrético indeniza deteriorações culposas e frutos que deixou de obter por negligência.", "Quem administra o imóvel dado em garantia responde pela perda evitável e pela exploração descuidada.", "Credor deixa colheita apodrecer e deve compensar o rendimento que poderia ter recebido.", "A responsabilidade exige culpa ou negligência e relação com o prejuízo demonstrado.", "Frutos", "rendimentos periódicos produzidos pelo bem sem destruição de sua substância"),
"1509": ("Anticrese registrada é oponível ao adquirente e a credores sem garantia ou hipotecários posteriores, mas certas omissões na execução, seguro ou desapropriação retiram preferência.", "A prioridade real depende do registro e do exercício oportuno do direito de retenção, com exceções legais.", "Credor que não opõe retenção durante execução perde preferência sobre o preço obtido.", "A garantia não prefere automaticamente à indenização securitária ou expropriatória.", "Credor quirografário", "credor sem garantia real ou preferência legal específica"),
"1510": ("Adquirente do imóvel em anticrese pode liberá-lo antes do vencimento pagando toda a dívida calculada na data do pedido e, se necessário, tomar posse.", "A lei permite antecipar a desoneração integral do bem mediante satisfação completa do crédito.", "Comprador quita saldo total e requer a posse antes retida pelo credor anticrético.", "Não basta pagamento parcial; o cálculo deve refletir a dívida total na data da remição.", "Imissão na posse", "entrada jurídica e material de alguém na posse do bem"),
"1510-A": ("O dono da construção-base pode instituir unidade autônoma acima ou abaixo dela, com matrícula, encargos e disponibilidade próprios, sem fração ideal do terreno; lajes sucessivas exigem autorizações e regras urbanísticas.", "O direito real de laje separa verticalmente unidades, sem criar condomínio necessário sobre o solo ou áreas preexistentes.", "Proprietário registra moradia independente sobre sua casa, e o titular paga tributos da nova unidade.", "Instituição, matrícula, segurança estrutural e normas municipais são indispensáveis; laje não é mera locação.", "Construção-base", "edificação original sobre ou sob a qual se constitui a laje"),
"1510-B": ("Titular da laje não pode, por obra ou falta de reparo, comprometer segurança, arquitetura ou estética do edifício e deve observar normas locais.", "A autonomia da unidade vertical encontra limite na integridade e harmonia do conjunto edificado.", "Titular precisa reparar infiltração que ameaça estrutura comum e não pode ampliar irregularmente a fachada.", "Autorização privada não substitui licenças urbanísticas nem afasta responsabilidade por danos.", "Postura edilícia", "regra municipal sobre construção, conservação e uso de edificações"),
"1510-C": ("Despesas das estruturas, coberturas, instalações e serviços comuns são repartidas conforme contrato; qualquer interessado pode executar reparo urgente nos termos legais.", "Construção-base e lajes custeiam o que serve ao prédio inteiro, preservando resposta imediata a risco.", "Moradores dividem conserto da coluna comum na proporção contratada e um deles contém vazamento urgente.", "Uso exclusivo aparente de cobertura não impede sua natureza comum quando protege todo o edifício.", "Parte comum", "estrutura ou instalação destinada ao funcionamento do edifício como conjunto"),
"1510-D": ("Na venda de unidade sobreposta, base e lajes têm preferência em ordem legal, com aviso escrito e trinta dias; omitida a ciência, cabe aquisição mediante depósito em cento e oitenta dias.", "A preferência facilita reunião coerente das unidades e protege titulares próximos, sem impedir venda a terceiro após o procedimento.", "Dono da base não é avisado e deposita o preço para adquirir a laje dentro do prazo decadencial.", "Contrato pode disciplinar o prazo inicial, mas a reação por falta de aviso exige depósito e observância da decadência.", "Preferência", "direito de comprar nas mesmas condições oferecidas a terceiro"),
"1510-E": ("Ruína da construção-base extingue a laje, salvo unidade subterrânea ou reconstrução em cinco anos, sem excluir indenização contra o responsável.", "A existência física da base sustenta o direito vertical, com exceções que permitem continuidade ou recomposição.", "Edifício desaba, mas é reconstruído no prazo legal e a laje pode subsistir.", "A extinção real e a responsabilidade civil são questões distintas; culpa pode gerar reparação.", "Ruína", "destruição ou colapso relevante da construção que sustenta a unidade"),
"1511": ("O casamento estabelece projeto comum de vida baseado em igualdade de direitos e deveres entre os cônjuges.", "Nenhum integrante ocupa posição jurídica superior na condução da família e das responsabilidades conjugais.", "Decisões patrimoniais e familiares são discutidas pelo casal em condição igual.", "A aplicação contemporânea protege igualmente casamentos independentemente do sexo dos cônjuges.", "Comunhão de vida", "vínculo de cooperação pessoal, afetiva e material formado pelo casamento"),
"1512": ("A celebração civil do casamento é gratuita; pessoas que declarem pobreza também têm isenção na habilitação, registro e primeira certidão.", "A falta de recursos não pode impedir acesso ao casamento civil e à documentação inicial.", "Casal sem condições econômicas obtém habilitação e primeira certidão sem custas.", "A isenção documental ampliada depende da declaração de pobreza sob responsabilidade legal.", "Emolumentos", "valores cobrados por serviços notariais e registrais"),
"1513": ("Pessoas e entidades públicas ou privadas não podem interferir indevidamente na vida comum instituída pela família.", "A autonomia familiar recebe proteção contra ingerências externas arbitrárias.", "Terceiro não pode impor ao casal como organizar sua convivência privada.", "A proteção não impede medidas legais para resguardar crianças, vulneráveis ou direitos de terceiros.", "Autonomia familiar", "liberdade de organizar a vida familiar dentro dos limites jurídicos"),
"1514": ("O casamento forma-se quando os nubentes manifestam consentimento perante a autoridade e esta declara o vínculo.", "Vontade livre, solenidade e declaração oficial compõem o momento constitutivo do casamento civil.", "Duas pessoas habilitadas confirmam sua vontade e são declaradas casadas pela autoridade.", "A referência literal a homem e mulher deve ser aplicada conforme a igualdade e o reconhecimento jurídico contemporâneo do casamento entre pessoas do mesmo sexo.", "Nubente", "pessoa que está prestes a contrair casamento"),
"1515": ("Casamento religioso que cumpra os requisitos civis e seja registrado equipara-se ao civil, com efeitos desde a cerimônia.", "A celebração confessional pode produzir efeitos estatais mediante habilitação e publicidade registral.", "Casal celebra rito religioso, registra-o corretamente e obtém efeitos civis desde aquela data.", "Sem requisitos e registro próprios, a cerimônia não adquire automaticamente efeitos civis.", "Efeito retroativo", "produção de consequências jurídicas desde data anterior ao registro"),
"1516": ("O registro do casamento religioso segue requisitos civis, normalmente em noventa dias; fora do prazo ou sem formalidades, exige nova ou prévia habilitação, e casamento civil anterior impede o registro.", "O sistema verifica capacidade e impedimentos antes de reconhecer civilmente a cerimônia religiosa.", "Registro pedido após noventa dias só prossegue depois de nova habilitação.", "Registro não convalida bigamia e cada hipótese possui procedimento próprio de habilitação.", "Habilitação", "procedimento prévio que verifica capacidade e ausência de impedimentos"),
"1517": ("A partir de dezesseis anos é possível casar com autorização de ambos os pais ou representantes até a maioridade; divergência pode ser resolvida judicialmente.", "A idade núbil não elimina a proteção decorrente da incapacidade civil relativa.", "Jovem de dezessete anos apresenta autorização dos responsáveis antes da celebração.", "A regra deve ser lida com a proibição absoluta de casamento abaixo de dezesseis anos.", "Idade núbil", "idade mínima legal para contrair casamento"),
"1518": ("Pais ou tutores podem retirar a autorização para casar até o momento da celebração.", "Consentimento representativo não se torna irrevogável antes de formado o vínculo.", "Responsáveis revogam por escrito a autorização antes da cerimônia e o casamento é suspenso.", "Depois de celebrado o casamento, a simples revogação já não produz esse efeito preventivo.", "Revogação", "retirada válida de autorização anteriormente concedida"),
"1519": ("Quando a negativa de consentimento for injusta, o juiz pode suprir a autorização.", "O controle judicial evita que poder familiar ou tutela impeça casamento por motivo arbitrário.", "Responsável recusa sem fundamento e o adolescente obtém suprimento após análise judicial.", "O suprimento não é automático e depende de avaliação do caso e dos demais requisitos matrimoniais.", "Suprimento judicial", "decisão que substitui consentimento indevidamente negado"),
"1520": ("É proibido, sem exceção, casamento de pessoa abaixo da idade núbil de dezesseis anos.", "A lei eliminou antigas permissões excepcionais para casamento infantil.", "Cartório recusa habilitação de pessoa com quinze anos mesmo diante de gravidez.", "União de fato ou gravidez não afasta a proibição legal nem antecipa a idade núbil.", "Proibição absoluta", "vedação que não admite as exceções antes existentes"),
"1521": ("Impedimentos matrimoniais alcançam parentesco em linhas e graus definidos, adoção, vínculo conjugal ainda existente e homicídio ou tentativa contra o consorte.", "Essas situações atingem a própria validade do casamento por razões familiares, monogâmicas e protetivas.", "Pessoa ainda casada não pode celebrar novo casamento antes da dissolução do vínculo.", "Impedimento não se confunde com causa suspensiva e exige conferir parentesco e situação jurídica concretos.", "Impedimento matrimonial", "circunstância que proíbe validamente a celebração do casamento"),
"1522": ("Qualquer pessoa capaz pode alegar impedimento até a celebração; juiz e registrador devem declará-lo se dele tiverem conhecimento.", "A tutela da validade matrimonial não depende apenas da iniciativa dos nubentes.", "Parente apresenta prova de casamento anterior antes da cerimônia e o ato é impedido.", "A oposição precisa indicar fato real e pode gerar responsabilidade se formulada de má-fé.", "Oposição", "comunicação formal de obstáculo jurídico ao casamento"),
"1523": ("Certas situações patrimoniais ou familiares recomendam adiar o casamento; o juiz pode afastar algumas mediante prova de ausência de prejuízo ou de gravidez.", "As causas suspensivas protegem herdeiros, ex-cônjuge, tutelado e certeza sobre filiação, sem tornar o casamento absolutamente impossível.", "Divorciado prova que a partilha não prejudica o ex-cônjuge e pede afastamento da suspensão.", "Casamento realizado apesar da causa pode atrair regime patrimonial obrigatório, e cada dispensa exige prova específica.", "Causa suspensiva", "situação que recomenda adiar o casamento sem constituir impedimento absoluto"),
"1524": ("Causas suspensivas podem ser alegadas por parentes em linha reta e por colaterais de segundo grau, consanguíneos ou afins.", "A lei restringe legitimidade a familiares próximos, diferentemente dos impedimentos.", "Irmão de nubente informa formalmente causa suspensiva documentada.", "A alegação deve ocorrer no procedimento adequado e não autoriza intervenção de qualquer terceiro.", "Legitimidade", "aptidão jurídica para formular determinado pedido ou oposição"),
"1525": ("Pedido de habilitação é assinado pelos nubentes ou procurador e acompanhado de documentos sobre nascimento, autorização, testemunhas, estado civil, residência e vínculos anteriores.", "A documentação permite ao registro verificar identidade, capacidade e inexistência de obstáculo matrimonial.", "Viúvo junta certidão de óbito e demais declarações ao requerer habilitação.", "Documento faltante ou situação anterior não comprovada pode impedir a emissão do certificado.", "Habilitação matrimonial", "procedimento documental que antecede a celebração civil"),
"1526": ("A habilitação ocorre pessoalmente no Registro Civil com audiência do Ministério Público; impugnação do oficial, órgão ministerial ou terceiro leva o caso ao juiz.", "O registrador conduz a fase administrativa e controvérsias relevantes recebem controle judicial.", "Terceiro documenta impedimento e a habilitação é submetida à decisão judicial.", "Participação do Ministério Público não substitui a apreciação judicial quando houver impugnação.", "Audiência do Ministério Público", "intervenção institucional para examinar a regularidade do procedimento"),
"1527": ("Documentação regular gera proclamas afixados por quinze dias e publicados localmente quando houver imprensa; urgência pode justificar dispensa da publicação.", "A publicidade permite conhecimento e oposição de impedimentos antes da cerimônia.", "Cartório publica edital nas circunscrições dos dois nubentes durante o prazo legal.", "Dispensa excepcional da publicação exige decisão da autoridade competente e não elimina outros requisitos.", "Proclamas", "edital público que anuncia a intenção de casamento"),
"1528": ("O registrador deve explicar aos nubentes fatos que invalidam casamento e os regimes de bens disponíveis.", "A habilitação também cumpre função informativa para consentimento consciente e planejamento patrimonial.", "Oficial esclarece diferença entre comunhão parcial e separação antes da escolha.", "O dever de informação não substitui aconselhamento jurídico individual em situação complexa.", "Regime de bens", "conjunto de regras sobre patrimônio dos cônjuges"),
"1529": ("Impedimento ou causa suspensiva é oposto por declaração escrita, assinada e acompanhada de prova ou indicação de onde obtê-la.", "A formalidade reduz acusações vagas e permite contraditório verificável.", "Oponente junta certidão que demonstra vínculo matrimonial ainda vigente.", "Alegação sem suporte pode ser rejeitada e a má-fé pode gerar consequências.", "Prova documental", "registro escrito usado para demonstrar o fato alegado"),
"1530": ("O oficial entrega aos nubentes nota com fundamentos, provas e identidade do oponente; eles podem pedir prazo para contraprova e agir contra oposição maliciosa.", "O procedimento assegura informação, defesa e responsabilização por abuso.", "Nubentes recebem a nota, apresentam certidão contrária e processam oponente comprovadamente doloso.", "A reação civil ou criminal exige elementos de má-fé, não simples erro justificável.", "Contraprova", "elemento apresentado para afastar ou enfraquecer a alegação adversa"),
"1531": ("Cumpridas as formalidades e inexistindo obstáculo, o oficial emite certificado de habilitação.", "O documento confirma que a verificação prévia foi concluída, permitindo agendar a celebração.", "Após proclamas sem oposição, casal recebe certificado para a cerimônia.", "O certificado possui validade limitada e não autoriza ignorar impedimento supervenientemente conhecido.", "Certificado de habilitação", "documento registral que atesta aptidão verificada para casar"),
"1532": ("O certificado de habilitação produz efeitos por noventa dias desde sua emissão.", "A cerimônia deve ocorrer dentro desse período ou será necessária nova habilitação.", "Casal adia a celebração além de noventa dias e reinicia o procedimento.", "O prazo conta da extração do certificado, não da publicação dos proclamas.", "Eficácia", "período em que o documento pode produzir seus efeitos jurídicos"),
"1533": ("Casamento é celebrado no dia, horário e local definidos pela autoridade, a pedido de contraentes devidamente habilitados.", "A cerimônia depende de organização oficial e certificado válido.", "Nubentes apresentam habilitação e comparecem ao ato previamente designado.", "Mudanças de local ou data devem respeitar publicidade, autoridade competente e validade da habilitação.", "Autoridade celebrante", "agente legalmente competente para presidir o casamento"),
"1534": ("A solenidade é pública, de portas abertas e com testemunhas; fora do cartório ou havendo impossibilidade de escrever, aumentam-se as cautelas testemunhais.", "Publicidade e testemunhas comprovam liberdade e regularidade da manifestação matrimonial.", "Cerimônia em residência permanece aberta e conta com quatro testemunhas.", "Quantidade de testemunhas varia conforme local e capacidade de assinatura dos contraentes.", "Solenidade", "forma pública e formal exigida para a celebração"),
"1535": ("Nubentes, pessoalmente ou por procurador especial, afirmam vontade livre diante de autoridade, testemunhas e oficial, sendo então declarados casados.", "O vínculo nasce da convergência entre consentimento inequívoco e declaração oficial.", "Procurador com poderes especiais representa nubente e a autoridade confirma o casamento.", "Representação exige procuração pública específica e consentimento não pode estar viciado.", "Procurador especial", "representante com poderes expressos para celebrar determinado casamento"),
"1536": ("Após a cerimônia, o registro reúne identificação de cônjuges e pais, casamento anterior, datas, documentos, testemunhas, regime patrimonial e nome adotado.", "O assento cria prova pública detalhada do vínculo e de escolhas relevantes.", "Oficial registra regime de bens e sobrenome escolhido logo depois da celebração.", "O conteúdo deve ser completo e assinado pelos participantes previstos, com correções feitas pela via registral adequada.", "Assento", "registro oficial do casamento lavrado no livro civil"),
"1537": ("A autorização para casar deve ser integralmente transcrita na escritura antenupcial.", "A incorporação preserva prova do consentimento exigido e vincula-o ao planejamento patrimonial.", "Escritura do regime escolhido reproduz toda a autorização dada aos nubentes menores.", "A regra aplica-se quando há autorização e pacto antenupcial, sem dispensar demais formalidades.", "Escritura antenupcial", "instrumento público que estabelece regime patrimonial antes do casamento"),
"1538": ("A cerimônia é suspensa diante de recusa, falta de liberdade ou arrependimento manifestado por nubente, que não pode retratar-se no mesmo dia.", "A lei protege consentimento atual e evita pressão para prosseguir imediatamente após hesitação.", "Nubente declara estar coagido e a autoridade interrompe o ato.", "A suspensão não equivale automaticamente a cancelamento definitivo, mas impede conclusão naquele dia.", "Consentimento livre", "vontade manifestada sem coação ou constrangimento relevante"),
"1539": ("Doença grave permite celebração urgente onde estiver o nubente, inclusive à noite, com testemunhas; substitutos suprem ausências e o termo extraordinário é registrado em cinco dias.", "O procedimento adapta a forma sem abandonar documentação, competência e controle posterior.", "Autoridade vai ao hospital e oficial ad hoc registra o termo no prazo legal.", "Urgência e moléstia devem ser reais; testemunhas e registro posterior continuam indispensáveis.", "Oficial ad hoc", "pessoa designada especificamente para exercer a função naquele ato"),
"1540": ("Em risco iminente de morte e sem autoridade disponível, nubentes podem casar perante seis testemunhas sem parentesco próximo.", "O casamento nuncupativo preserva a vontade em emergência extrema, sujeito a confirmação posterior.", "Paciente em perigo declara casamento diante de seis testemunhas idôneas.", "A exceção exige simultaneamente risco de vida e impossibilidade de obter autoridade ou substituto.", "Casamento nuncupativo", "casamento emergencial celebrado sem autoridade presente"),
"1541": ("Testemunhas do casamento emergencial comparecem ao juiz em dez dias, relatam convocação, lucidez, perigo e consentimento; segue investigação, decisão e registro com efeitos desde a cerimônia.", "A validação judicial substitui cautelas ausentes no momento crítico e verifica capacidade matrimonial.", "Testemunhas prestam declarações e o juiz confirma o vínculo após diligências.", "Prazos, conteúdo dos depoimentos e ausência de impedimentos são essenciais à confirmação.", "Ratificação judicial", "reconhecimento posterior da validade de ato emergencial"),
"1542": ("Casamento por procuração exige instrumento público, poderes especiais e mandato de até noventa dias; revogação também é pública e pode gerar indenização se desconhecida.", "A representação é excepcional e rigidamente formal, preservando vontade atual e responsabilidade do mandante.", "Nubente no exterior outorga procuração específica válida para a data da cerimônia.", "Revogação pode impedir o vínculo mesmo sem ciência do mandatário, sem afastar eventuais perdas e danos.", "Mandato matrimonial", "procuração específica para manifestação de vontade na cerimônia"),
"1543": ("Casamento celebrado no Brasil prova-se pelo registro; se o assento faltar ou se perder justificadamente, admitem-se outros meios de prova.", "A certidão é prova normal, mas sua ausência material não torna impossível demonstrar o vínculo.", "Incêndio destrói livro e testemunhos e documentos reconstituem a celebração.", "A prova alternativa exige justificar a falta do registro e demonstrar efetivamente o casamento.", "Prova supletiva", "meio alternativo usado quando o documento principal não existe"),
"1544": ("Casamento de brasileiro realizado no exterior deve ser registrado no Brasil em cento e oitenta dias da volta de um dos cônjuges, no cartório territorial indicado.", "A transcrição integra o ato estrangeiro ao sistema registral brasileiro e facilita sua publicidade.", "Brasileiro retorna e registra em seu domicílio o casamento celebrado perante autoridade estrangeira.", "Validade estrangeira, documentos e regras de direito internacional também precisam ser conferidos.", "Transcrição", "registro nacional de ato civil celebrado no exterior"),
"1545": ("Posse pública do estado de casados protege filhos quando cônjuges faleceram ou não podem manifestar vontade, salvo prova registral de casamento anterior de um deles.", "A aparência familiar consolidada pode suprir prova em benefício da prole, sem legitimar bigamia comprovada.", "Filhos demonstram convivência social dos pais como casados após perda do registro.", "A regra protege a prole e não supera certidão que revele impedimento matrimonial anterior.", "Posse do estado de casado", "reconhecimento social contínuo de duas pessoas como cônjuges"),
"1546": ("Reconhecida judicialmente a celebração, o registro da sentença produz efeitos civis desde a data original para cônjuges e filhos.", "A decisão e sua inscrição reconstituem a prova do vínculo com alcance retroativo.", "Sentença comprova casamento antigo e o registro preserva efeitos desde a cerimônia.", "Terceiros e situações consolidadas podem exigir análise conjunta de boa-fé e segurança jurídica.", "Sentença declaratória", "decisão que reconhece situação jurídica preexistente"),
"1547": ("Na dúvida equilibrada entre provas, prevalece a existência do casamento quando houve posse do estado de casados.", "O favor ao casamento estabiliza relação familiar socialmente reconhecida diante de incerteza probatória.", "Documentos conflitantes são avaliados junto à convivência pública e duradoura como cônjuges.", "A presunção atua na dúvida real e não vence prova segura de impedimento ou inexistência.", "Favor matrimonii", "orientação que favorece preservar o casamento em dúvida probatória"),
"1548": ("É nulo o casamento que viola impedimento matrimonial; a antiga hipótese ligada à enfermidade mental foi revogada.", "Nulidade decorre de obstáculo legal grave existente na celebração, não da deficiência da pessoa.", "Casamento de pessoa já casada é impugnado por infringir impedimento.", "Não se pode reintroduzir a hipótese revogada nem tratar deficiência como incapacidade matrimonial automática.", "Nulidade", "invalidade grave que atinge o casamento por violação de impedimento"),
"1549": ("Qualquer interessado juridicamente afetado ou o Ministério Público pode propor ação direta para declarar nulidade por impedimento.", "A legitimidade é mais ampla porque a nulidade protege valores públicos e familiares relevantes.", "Ministério Público ajuíza ação ao comprovar casamento celebrado durante vínculo anterior.", "Interesse precisa ser jurídico e a nulidade depende de decisão no procedimento adequado.", "Ação direta", "processo autônomo voltado à declaração judicial de nulidade"),
"1550": ("Casamento é anulável por idade, falta de autorização, vício de vontade, incapacidade de consentir, mandato revogado desconhecido ou autoridade incompetente; deficiência não impede consentimento por si.", "As hipóteses protegem formação válida da vontade e regularidade do ato, com efeitos até decisão anulatória.", "Nubente coagido pede anulação dentro do prazo correspondente.", "Anulabilidade difere de nulidade, possui legitimados e prazos próprios e não presume incapacidade da pessoa com deficiência.", "Anulabilidade", "invalidade dependente de iniciativa e prazo previstos em lei"),
"1551": ("Casamento do qual resultou gravidez não é anulado apenas por falta da idade mínima.", "A norma preserva efeitos familiares em situação específica ligada à prole.", "Cônjuge não obtém anulação exclusivamente etária quando o casamento resultou em gravidez.", "A regra não autoriza previamente casamento abaixo de dezesseis anos, hoje proibido de modo absoluto.", "Convalidação", "preservação de ato que apresentava causa de anulabilidade"),
"1552": ("Anulação de casamento de menor de dezesseis anos pode ser requerida pelo próprio cônjuge, representantes ou ascendentes.", "A lei delimita quem pode atacar o vínculo por idade inferior à mínima.", "Ascendente propõe ação em favor de pessoa casada antes dos dezesseis anos.", "A hipótese deve ser compatibilizada com a proibição atual e os prazos legais da ação.", "Legitimado", "pessoa autorizada pela lei a propor determinada ação"),
"1553": ("Quem casou antes da idade núbil pode confirmar o vínculo ao atingir essa idade, com autorização ainda necessária ou suprimento judicial.", "A confirmação remove a causa etária de anulabilidade mediante vontade renovada e controle protetivo.", "Ao completar dezesseis anos, jovem confirma o casamento com autorização judicial.", "A regra trata efeito de casamento já ocorrido e não cria permissão atual para casamento infantil.", "Confirmação", "ato que preserva vínculo antes sujeito a anulação"),
"1554": ("Subsiste casamento presidido por pessoa sem competência legal que exercia publicamente a função e registrou o ato nessa qualidade.", "A aparência legítima da autoridade protege boa-fé e estabilidade do estado civil.", "Casal casa perante agente publicamente reconhecido como juiz de casamentos e o registro é mantido.", "A proteção exige exercício público da função e registro, não qualquer cerimônia privada irregular.", "Autoridade aparente", "pessoa que publicamente exerce função embora falte competência formal"),
"1555": ("Casamento de menor em idade núbil sem autorização só pode ser anulado por legitimados em cento e oitenta dias; presença ou aprovação dos representantes impede a anulação por esse motivo.", "A lei limita temporalmente a impugnação e reconhece consentimento demonstrado de forma inequívoca.", "Representante que participou da cerimônia não pode depois alegar simples ausência de autorização formal.", "O início do prazo varia conforme incapaz, representantes ou herdeiros e deve ser calculado individualmente.", "Prazo decadencial", "período após o qual se extingue o direito de anular o ato"),
"1556": ("Erro essencial sobre a pessoa do outro nubente pode viciar o consentimento e tornar o casamento anulável.", "Não basta frustração comum: o erro deve alcançar característica juridicamente relevante prevista na lei.", "Cônjuge descobre fato anterior grave que se enquadra nas hipóteses legais e pede anulação.", "A avaliação exige nexo com o consentimento e respeito ao rol e à interpretação constitucional vigente.", "Erro essencial", "equívoco decisivo sobre qualidade juridicamente relevante da pessoa"),
"1557": ("Erro essencial pode envolver identidade, honra, crime anterior ou condição física ou doença grave transmissível nos limites legais; a hipótese relativa à deficiência foi revogada.", "A anulação depende de desconhecimento anterior e gravidade capaz de tornar insuportável a vida comum ou gerar risco previsto.", "Crime grave anterior, ignorado pelo cônjuge, fundamenta pedido quando inviabiliza a convivência.", "Deficiência não é defeito jurídico nem causa autônoma; intimidade, dignidade e não discriminação orientam a aplicação.", "Moléstia transmissível", "doença capaz de transmissão por contágio ou herança nas condições legais"),
"1558": ("Coação que provoque temor fundado de dano grave e iminente à vida, saúde ou honra do nubente ou familiar torna o casamento anulável.", "Consentimento matrimonial deve resultar de escolha livre, não de ameaça relevante.", "Pessoa casa sob ameaça séria contra familiar e depois busca a anulação.", "Temor precisa ser fundado, considerável e causal para a manifestação de vontade.", "Coação", "pressão mediante ameaça que compromete a liberdade de decidir"),
"1559": ("Somente quem errou ou sofreu coação pede anulação; convivência após conhecer o vício pode confirmar o casamento, ressalvadas hipóteses legais específicas.", "O direito pertence ao cônjuge protegido e pode desaparecer se ele aceita conscientemente a vida comum.", "Após descobrir erro, cônjuge continua voluntariamente a convivência e pode convalidar o vínculo.", "Coabitação deve revelar aceitação livre; exceções legais e eventual violência exigem análise cuidadosa.", "Coabitação", "vida comum mantida pelos cônjuges após a celebração"),
"1560": ("Ações de anulação têm prazos diferentes conforme incapacidade, autoridade incompetente, erro, coação ou mandato, geralmente contados da celebração ou da ciência indicada.", "A decadência varia pela causa e pelo legitimado, exigindo identificação precisa do fundamento.", "Coação sujeita-se ao prazo de quatro anos, enquanto mandato revogado tem prazo de cento e oitenta dias da ciência.", "Incisos revogados ou alterados não podem ser aplicados isoladamente; termo inicial e hipótese devem ser conferidos.", "Termo inicial", "evento a partir do qual começa a contagem do prazo"),
"1561": ("Casamento putativo produz efeitos até a sentença para cônjuge de boa-fé e filhos; mesmo a má-fé de ambos não prejudica os filhos.", "A proteção da confiança e da filiação limita efeitos destrutivos da invalidade.", "Pessoa desconhecia impedimento e preserva efeitos civis anteriores à anulação.", "Boa-fé é examinada separadamente para cada cônjuge, enquanto filhos recebem proteção independente.", "Casamento putativo", "casamento inválido celebrado com boa-fé de ao menos um cônjuge"),
"1562": ("Antes ou durante ações familiares indicadas, a parte necessitada pode pedir separação de corpos com decisão célere.", "A medida afasta convivência e organiza proteção imediata sem antecipar todo o mérito da ação.", "Pessoa em risco pede afastamento físico antes de propor divórcio.", "Hoje a tutela deve ser articulada com medidas protetivas e regras processuais atuais quando houver violência.", "Separação de corpos", "medida judicial que autoriza cessar a convivência física"),
"1563": ("A nulidade retroage à celebração, mas preserva direitos onerosos de terceiros de boa-fé e efeitos de decisão judicial definitiva.", "A restauração ao estado anterior cede diante da confiança legítima e da coisa julgada.", "Comprador de boa-fé mantém aquisição onerosa feita antes da sentença de nulidade.", "Proteção exige boa-fé e onerosidade; efeitos do casamento putativo também precisam ser considerados.", "Efeito retroativo", "consequência jurídica projetada para data anterior à decisão"),
"1564": ("Cônjuge culpado pela anulação perde vantagens recebidas do inocente e deve cumprir promessas do pacto antenupcial.", "A norma impõe consequências patrimoniais à conduta que causou a invalidade.", "Quem ocultou impedimento perde benefício dado pelo cônjuge de boa-fé.", "Culpa, validade das promessas e compatibilidade constitucional precisam ser demonstradas no caso concreto.", "Contrato antenupcial", "ajuste patrimonial celebrado antes do casamento"),
"1565": ("Cônjuges assumem parceria e encargos familiares; qualquer um pode adotar sobrenome do outro e o planejamento familiar é livre, sem coerção estatal ou privada.", "Igualdade, autonomia nominal e decisão reprodutiva conjunta estruturam os efeitos pessoais do casamento.", "Um cônjuge acrescenta o sobrenome do outro e ambos decidem livremente sobre filhos.", "A linguagem binária do texto recebe aplicação igualitária, inclusive em casamentos entre pessoas do mesmo sexo.", "Planejamento familiar", "decisão livre e informada sobre formação e organização reprodutiva da família"),
"1566": ("Deveres conjugais incluem fidelidade, vida comum, assistência, cuidado com filhos e respeito recíproco.", "O casamento cria obrigações pessoais de cooperação, proteção e responsabilidade parental.", "Cônjuges dividem cuidados dos filhos e apoiam-se durante doença.", "Violação não autoriza coerção sobre intimidade nem restaura requisitos de culpa para obter divórcio.", "Mútua assistência", "dever recíproco de apoio material e pessoal"),
"1567": ("A direção familiar cabe conjuntamente aos cônjuges, no interesse do casal e dos filhos; divergência pode ser submetida ao juiz.", "Igualdade substitui antiga chefia unilateral e orienta decisões familiares compartilhadas.", "Cônjuges discordam sobre decisão essencial dos filhos e buscam solução judicial.", "Intervenção judicial é subsidiária e deve respeitar autonomia e melhor interesse das crianças.", "Direção familiar", "coordenação das decisões relevantes da vida comum"),
"1568": ("Ambos contribuem para sustento da família e educação dos filhos proporcionalmente a bens e renda, qualquer que seja o regime patrimonial.", "Responsabilidade familiar considera capacidade econômica e não depende de titularidade formal dos bens.", "Cônjuge com renda maior assume parcela proporcionalmente superior das despesas.", "Proporcionalidade não significa divisão necessariamente igual e trabalho de cuidado também integra a realidade familiar.", "Encargos familiares", "despesas e responsabilidades necessárias à manutenção da família"),
"1569": ("Domicílio do casal é escolhido em conjunto, e cada cônjuge pode ausentar-se por função pública, profissão ou interesse particular relevante.", "A vida comum não elimina liberdade profissional e pessoal nem autoriza imposição unilateral de residência.", "Cônjuge aceita trabalho temporário em outra cidade por razão profissional relevante.", "Ausência legítima não se confunde automaticamente com abandono e deve ser avaliada no contexto.", "Domicílio conjugal", "local escolhido como centro da vida comum do casal"),
"1570": ("Quando um cônjuge está remoto, desaparecido, preso por mais de cento e oitenta dias, interditado ou temporariamente inconsciente, o outro dirige a família e administra bens.", "A regra assegura continuidade decisória diante de impossibilidade relevante de participação.", "Cônjuge administra patrimônio comum durante longa prisão do outro.", "Poder exclusivo é funcional e temporário, sujeito a deveres patrimoniais e eventual controle judicial.", "Administração dos bens", "gestão e conservação do patrimônio familiar"),
"1571": ("A sociedade conjugal termina por morte, invalidade, separação ou divórcio; o casamento válido dissolve-se por morte ou divórcio, e o nome pode ser preservado.", "A norma distingue fim dos deveres conjugais e dissolução definitiva do vínculo que permite novo casamento.", "Divórcio encerra vínculo e não exige que o ex-cônjuge abandone automaticamente o sobrenome adotado.", "O divórcio direto não depende hoje de prévia separação nem de prazo, conforme a Constituição.", "Vínculo conjugal", "estado civil matrimonial cuja dissolução permite novo casamento"),
"1572": ("O texto disciplina separação judicial por violação grave, ruptura prolongada ou doença mental, com consequências patrimoniais específicas.", "Essas hipóteses pertencem ao regime literal de separação e não condicionam o direito potestativo ao divórcio.", "Cônjuge pode pedir diretamente divórcio sem provar culpa ou doença do outro.", "Doença ou deficiência não deve ser tratada discriminatoriamente; a aplicação exige leitura constitucional posterior.", "Direito potestativo", "poder de produzir efeito jurídico sem depender da concordância da outra parte"),
"1573": ("O Código enumera fatos que podiam demonstrar impossibilidade de vida comum e permite ao juiz considerar outros.", "Adultério, violência, abandono e condutas graves são elementos do antigo regime de separação, não requisitos do divórcio atual.", "Tentativa de morte fundamenta medidas protetivas e pode ser relatada sem ser necessária para dissolver o vínculo.", "A enumeração não autoriza culpabilização automática nem restringe o divórcio direto.", "Sevícia", "maus-tratos físicos ou crueldade praticados contra o cônjuge"),
"1574": ("O texto prevê separação judicial consensual homologada, com controle de interesses dos filhos e cônjuges.", "A convenção organiza efeitos pessoais e patrimoniais, mas não limita o acesso contemporâneo ao divórcio consensual.", "Casal apresenta acordo sobre bens e filhos para controle judicial quando necessário.", "Prazo anual e separação prévia não são requisitos constitucionais do divórcio direto.", "Homologação", "aprovação judicial que confere eficácia ao acordo apresentado"),
"1575": ("Sentença de separação produz afastamento de corpos e partilha, que pode resultar de acordo homologado ou decisão judicial.", "A ruptura da convivência e a divisão patrimonial podem ser organizadas no mesmo processo.", "Juiz homologa proposta comum de divisão dos bens.", "Divórcio pode ocorrer sem partilha prévia; efeitos patrimoniais podem ser decididos depois.", "Partilha", "divisão dos bens comuns após término da relação"),
"1576": ("Separação judicial encerra coabitação, fidelidade e regime de bens; ação pertence aos cônjuges, com representação legal nas hipóteses previstas.", "O estado de separado afasta deveres conjugais selecionados sem necessariamente dissolver o vínculo matrimonial.", "Após separação, cessa o regime patrimonial, embora ainda não haja novo casamento.", "A disciplina não impede divórcio direto e representação deve observar capacidade e processo atuais.", "Sociedade conjugal", "conjunto de efeitos pessoais e patrimoniais mantidos durante o casamento"),
"1577": ("Cônjuges separados judicialmente podem restabelecer a sociedade conjugal por ato regular, preservados direitos de terceiros.", "A reconciliação reativa efeitos do casamento sem apagar negócios realizados durante a separação.", "Casal reconcilia-se em juízo, mas não desfaz garantia dada validamente a terceiro.", "O retorno exige formalização e não pode prejudicar situações patrimoniais já adquiridas.", "Reconciliação", "restabelecimento formal da sociedade conjugal após separação"),
"1578": ("O texto condiciona perda do sobrenome à culpa na separação, pedido do inocente e ausência de prejuízo de identificação, distinção dos filhos ou dano grave.", "Mesmo no regime literal, proteção da identidade limita a retirada do nome; atualmente prevalece autonomia pessoal após o divórcio.", "Pessoa mantém sobrenome para preservar identificação profissional e vínculo nominal com filhos.", "Culpa conjugal não deve ser transportada como requisito do divórcio e o nome integra direitos da personalidade.", "Nome de casado", "sobrenome incorporado em razão do casamento"),
"1579": ("Divórcio não altera responsabilidades parentais, e novo casamento dos pais não pode reduzi-las.", "Fim da conjugalidade não encerra poder familiar, sustento, convivência ou educação dos filhos.", "Pai divorciado continua participando das decisões escolares após novo casamento.", "Direitos dos filhos e deveres parentais são independentes do relacionamento afetivo entre os adultos.", "Parentalidade", "conjunto de vínculos, direitos e deveres entre pais e filhos"),
"1580": ("O texto antigo prevê conversão da separação em divórcio e divórcio por separação de fato após prazos determinados.", "A Constituição passou a admitir divórcio direto, sem causa, prazo ou separação prévia.", "Cônjuge requer divórcio imediatamente, ainda que não exista sentença de separação.", "Os prazos literais não podem ser apresentados como condição atual para dissolver o casamento.", "Divórcio direto", "dissolução do casamento sem etapa prévia de separação"),
"1581": ("Divórcio pode ser decretado antes da partilha do patrimônio.", "Divergência sobre bens não bloqueia a dissolução do vínculo matrimonial.", "Juiz decreta divórcio e mantém discussão patrimonial para fase posterior.", "A ausência de partilha exige cautela registral e não elimina direitos sobre bens comuns.", "Partilha posterior", "divisão patrimonial realizada depois da dissolução do casamento"),
"1582": ("O pedido de divórcio cabe aos cônjuges; incapaz pode atuar por representante indicado na lei.", "A dissolução é decisão pessoal dos integrantes do casamento, com proteção processual para incapacidade.", "Curador representa cônjuge incapaz em ação de divórcio.", "Representação não autoriza decidir contra interesses e vontade juridicamente aferível da pessoa protegida.", "Legitimidade exclusiva", "reserva do pedido às pessoas diretamente vinculadas ao casamento"),
"1583": ("Guarda pode ser unilateral ou compartilhada; esta divide responsabilidades e busca convivência equilibrada, com cidade-base favorável aos filhos e dever de fiscalização do genitor sem guarda.", "Compartilhar guarda significa corresponsabilidade, não divisão matemática do tempo nem alternância automática de residência.", "Pais separados decidem juntos sobre saúde e escola, ajustando convivência à rotina da criança.", "O melhor interesse dos filhos prevalece; incisos revogados e parágrafo vetado não produzem regra atual.", "Guarda compartilhada", "exercício conjunto de direitos e deveres parentais por pais separados"),
"1584": ("Guarda pode ser pedida ou fixada judicialmente; em regra é compartilhada entre genitores aptos, salvo recusa ou risco de violência, com apoio técnico e dever de informação de instituições.", "A preferência legal cede diante da segurança e das necessidades concretas da criança ou adolescente.", "Havendo indícios de violência doméstica, juiz não impõe compartilhamento automático e apura proteção adequada.", "Equilíbrio de convivência não se sobrepõe a risco, e descumprimento deve ser avaliado sem punir os filhos.", "Equipe interdisciplinar", "profissionais de áreas distintas que auxiliam a decisão sobre guarda"),
"1585": ("Decisão liminar de guarda deve preferencialmente ouvir ambos os lados, salvo urgência protetiva que justifique decisão sem prévia oitiva.", "Contraditório é regra, mas segurança imediata dos filhos pode exigir atuação judicial urgente.", "Juiz afasta provisoriamente risco grave antes de ouvir o outro genitor.", "Decisão sem oitiva é excepcional e deve ser posteriormente submetida ao contraditório.", "Liminar", "decisão provisória e urgente tomada antes do julgamento final"),
"1586": ("Motivo grave permite ao juiz organizar relação entre filhos e pais de modo diferente das regras anteriores, sempre em benefício dos filhos.", "A flexibilidade evita solução padronizada quando circunstâncias concretas exigem proteção especial.", "Juiz estabelece convivência supervisionada diante de risco comprovado.", "Gravidade precisa ser fundamentada e a medida deve ser proporcional ao melhor interesse.", "Convivência supervisionada", "contato acompanhado por pessoa ou serviço designado para proteção"),
"1587": ("Na invalidade do casamento com filhos comuns, aplicam-se as regras de guarda e proteção dos arts. 1.584 e 1.586.", "A invalidade da relação conjugal não diminui deveres parentais nem proteção infantil.", "Casamento anulado leva a plano de guarda compartilhada adequado aos filhos.", "Situação dos filhos é decidida por seus interesses, não como consequência punitiva da invalidade.", "Invalidade matrimonial", "nulidade ou anulação do casamento reconhecida juridicamente"),
"1588": ("Novo casamento do pai ou da mãe não retira guarda ou convivência; afastamento dos filhos exige ordem judicial e prova de tratamento inadequado.", "Recomposição familiar não presume incapacidade parental.", "Mãe casa novamente e mantém convivência, pois não há prova de risco aos filhos.", "A retirada exige processo e fundamento protetivo, não preconceito contra nova família.", "Recomposição familiar", "formação de novo núcleo afetivo após relação anterior"),
"1589": ("Genitor sem guarda pode conviver, acompanhar manutenção e educação dos filhos; avós também podem obter visita conforme decisão orientada pelo interesse da criança.", "Convivência familiar abrange contato e fiscalização responsável, sem ser prêmio dos adultos.", "Pai recebe informações escolares e avó obtém calendário de visitas benéfico ao neto.", "Convivência pode ser limitada quando houver risco e sempre se subordina à proteção infantil.", "Direito de convivência", "manutenção de relações pessoais entre criança e familiares"),
"1590": ("Regras sobre guarda e alimentos de filhos menores estendem-se a filhos maiores incapazes.", "A maioridade cronológica não encerra proteção quando incapacidade mantém necessidade de cuidado e sustento.", "Filho adulto com incapacidade continua recebendo alimentos e proteção de guarda adaptada.", "A medida deve respeitar autonomia possível e regime atual de capacidade e apoio à pessoa com deficiência.", "Maior incapaz", "adulto que necessita proteção jurídica por limitação reconhecida nos termos atuais"),
"1591": ("Parentes em linha reta descendem uns dos outros, como pais, filhos, avós e netos.", "A linha não possui limite de grau enquanto houver relação direta de ascendência ou descendência.", "Avó e neta são parentes em linha reta de segundo grau.", "Grau é contado por gerações e não se confunde com proximidade afetiva.", "Linha reta", "relação genealógica direta entre ascendente e descendente"),
"1592": ("Parentes colaterais até o quarto grau vêm de ancestral comum sem descender diretamente uns dos outros.", "Irmãos, tios, sobrinhos e primos integram a linha transversal dentro dos graus legais.", "Primos compartilham bisavós e são colaterais de quarto grau.", "A contagem sobe ao ascendente comum e desce ao outro parente.", "Parente colateral", "pessoa ligada por tronco comum sem relação direta de descendência"),
"1593": ("Parentesco pode resultar de consanguinidade ou de outra origem reconhecida pelo direito.", "A cláusula aberta inclui vínculos civis, como adoção e filiação socioafetiva juridicamente reconhecida, sem hierarquia entre origens.", "Filho adotivo possui parentesco civil completo com a família adotante.", "A origem biológica não confere superioridade e cada vínculo depende de reconhecimento jurídico adequado.", "Parentesco civil", "vínculo familiar decorrente de origem não exclusivamente consanguínea"),
"1594": ("Graus contam-se pelas gerações: diretamente na linha reta e, na colateral, subindo ao ancestral comum e descendo ao outro parente.", "O método determina distância jurídica para impedimentos, sucessão e outros efeitos.", "Entre tio e sobrinha há três gerações no percurso pelo ancestral comum.", "Não se conta o próprio ancestral comum como geração adicional.", "Grau de parentesco", "medida jurídica da distância entre parentes pelo número de gerações"),
"1595": ("Casamento ou união estável cria afinidade com parentes do cônjuge ou companheiro; limita-se a ascendentes, descendentes e irmãos, e não termina em linha reta com a dissolução.", "O vínculo impede certas relações mesmo após o fim do casal, especialmente entre sogros, genros, noras e enteados.", "Ex-genro continua afim em linha reta da antiga sogra.", "Afinidade não transforma todos os parentes de uma pessoa em parentes jurídicos do outro.", "Afinidade", "parentesco jurídico criado entre alguém e familiares próximos do parceiro"),
"1596": ("Todos os filhos têm iguais direitos e qualificações, sejam matrimoniais, extramatrimoniais ou adotivos, sendo proibida designação discriminatória.", "A origem da filiação não pode reduzir nome, alimentos, convivência, sucessão ou dignidade.", "Filho reconhecido fora do casamento herda em igualdade com os demais.", "Qualquer distinção hierárquica entre filhos viola a igualdade constitucional.", "Igualdade de filiação", "proibição de diferenças jurídicas baseadas na origem do vínculo filial"),
"1597": ("O Código estabelece presunções de concepção no casamento por prazos de nascimento e por reprodução assistida homóloga ou heteróloga autorizada.", "As presunções organizam filiação, inclusive em técnicas reprodutivas e após morte, sem impedir análise constitucional e probatória adequada.", "Filho decorrente de inseminação heteróloga previamente autorizada é presumido do casal.", "Consentimento reprodutivo, avanços médicos e pluralidade familiar exigem leitura atual; presunção não substitui toda investigação possível.", "Fecundação homóloga", "reprodução assistida com material genético do próprio casal"),
"1598": ("Se nova união ocorre durante período de dúvida, presume-se a filiação do primeiro marido em nascimento dentro de trezentos dias e do segundo após esse marco e prazo mínimo de convivência.", "A regra soluciona conflito cronológico entre presunções paternas sucessivas.", "Nascimento duzentos dias após morte do primeiro marido permanece sob a primeira presunção.", "Prova genética e direito à identidade podem influenciar o caso; os prazos são presunções, não ficções absolutas.", "Conflito de presunções", "sobreposição de regras que apontam pessoas diferentes como pai presumido"),
"1599": ("Prova de que o cônjuge não podia gerar na época da concepção afasta a presunção de paternidade.", "A presunção matrimonial cede diante de demonstração biológica pertinente ao período.", "Laudo comprova impossibilidade de procriação no momento relevante e permite impugnação.", "A prova deve ser robusta e respeitar identidade, filiação socioafetiva e melhor interesse.", "Ilidir", "afastar uma presunção mediante prova em contrário"),
"1600": ("Confissão de adultério pela mãe, sozinha, não afasta a paternidade presumida.", "A estabilidade da filiação não pode depender apenas de declaração unilateral sobre relacionamento extraconjugal.", "Mesmo com confissão materna, é necessária prova adequada para alterar o estado de filiação.", "A apuração deve proteger a criança e considerar vínculos biológicos e socioafetivos.", "Presunção de paternidade", "regra que atribui inicialmente paternidade em situação matrimonial"),
"1601": ("O marido pode contestar paternidade de filhos nascidos no casamento sem prazo prescricional, e seus herdeiros podem continuar ação já proposta.", "A imprescritibilidade permite discutir o estado de filiação, mas não elimina proteção a vínculos consolidados e direitos da criança.", "Autor propõe investigação e falece; herdeiros prosseguem no processo.", "Legitimidade literal, prova genética e parentalidade socioafetiva exigem ponderação conforme o caso atual.", "Imprescritível", "direito de ação que não se perde apenas pelo decurso do tempo"),
"1602": ("Confissão da mãe não é suficiente, isoladamente, para excluir paternidade.", "Estado filial não pode ser desfeito por declaração unilateral sem prova e processo adequados.", "Registro paterno permanece enquanto mera afirmação materna não é confirmada por outros elementos.", "Alterar filiação exige contraditório e consideração da identidade e do melhor interesse do filho.", "Estado de filiação", "posição jurídica e familiar de alguém como filho de determinada pessoa"),
"1603": ("A certidão do registro civil é prova ordinária da filiação.", "O assento de nascimento confere publicidade e segurança ao vínculo parental.", "Escola aceita certidão para comprovar quem são os pais registrados.", "Registro pode ser questionado por erro ou falsidade e não esgota outras origens de filiação reconhecidas.", "Certidão de nascimento", "documento público que reproduz dados do registro civil de nascimento"),
"1604": ("Ninguém pode exigir estado de filiação contrário ao registro sem provar erro ou falsidade.", "A estabilidade registral impede mudanças oportunistas, preservando via de correção quando o assento é defeituoso.", "Pessoa demonstra falsidade do registro para buscar retificação judicial.", "A regra deve conviver com investigação genética e reconhecimento socioafetivo conforme fundamentos próprios.", "Vindicar estado", "pedir reconhecimento de posição familiar diferente da registrada"),
"1605": ("Sem registro de nascimento, ou sendo ele defeituoso, filiação pode ser provada por meios admitidos, especialmente escrito dos pais ou fortes presunções baseadas em fatos certos.", "A falta documental não apaga identidade familiar quando outros elementos confiáveis demonstram o vínculo.", "Cartas dos pais e convivência pública consistente ajudam a provar filiação sem assento adequado.", "Presunções devem ser robustas e avaliadas com contraditório; exemplos legais não excluem outros meios lícitos.", "Começo de prova escrita", "documento inicial que torna plausível o fato a demonstrar"),
}

